class Solution {
public:
    int minimumChanges(string s, int k) {
        int n = s.length();
                const int INF = 1e9;
                        
                                // Precompute proper divisors for all possible lengths from 2 to n
                                     vector<vector<int>> divisors(n + 1);
                                                for (int len = 2; len <= n; ++len) {
                                                            for (int d = 1; d * 2 <= len; ++d) {
                                                                            if (len % d == 0) {
                                                                                                divisors[len].push_back(d);
                                                                                                                }
                                                                                                                            }
                                                                                                                                    }
                                                                                                                                            
                                                                                                                                                    // cost[i][j] = min changes to make substring s[i...j] a semi-palindrome
                                                                                                                                                            vector<vector<int>> cost(n, vector<int>(n, INF));
                                                                                                                                                                    for (int i = 0; i < n; ++i) {
                                                                                                                                                                                for (int j = i + 1; j < n; ++j) { // Substring length must be >= 2
                                                                                                                                                                                                int len = j - i + 1;
                                                                                                                                                                                                                for (int d : divisors[len]) {
                                                                                                                                                                                                                                    int changes = 0;
                                                                                                                                                                                                                                                        int groupLen = len / d;
                                                                                                                                                                                                                                                                            // Check each of the 'd' modulo groups
                                                                                                                                                                                                                                                                                                for (int rem = 0; rem < d; ++rem) {
                                                                                                                                                                                                                                                                                                                        for (int l = 0, r = groupLen - 1; l < r; ++l, --r) {
                                                                                                                                                                                                                                                                                                                                                    if (s[i + rem + l * d] != s[i + rem + r * d]) {
                                                                                                                                                                                                                                                                                                                                                                                    changes++;
                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                cost[i][j] = min(cost[i][j], changes);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    // dp[i][p] = min changes to partition prefix s[0...i-1] into 'p' semi-palindromes
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            vector<vector<int>> dp(n + 1, vector<int>(k + 1, INF));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    dp[0][0] = 0;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    for (int p = 1; p <= k; ++p) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // Each semi-palindrome has length >= 2, so i >= 2 * p
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            for (int i = 2 * p; i <= n; ++i) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            for (int prev = 2 * (p - 1); prev <= i - 2; ++prev) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (dp[prev][p - 1] != INF) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        dp[i][p] = min(dp[i][p], dp[prev][p - 1] + cost[prev][i - 1]);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                return dp[n][k];
    }
};